    return 0
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: TUPLE_ARR_HASH_LONG_NAME_COLLISION PASS
//
// Copilot review (PR #2516) finding #1 on the second review round:
// fo_name_hash/fo_name_hash2 (self-hosted/ir/lower.sio) used to cap their
// rolling hash at the first 64 bytes of the name, even though `Name.buf` is
// `[i8; 384]` and the parser accepts identifiers that long. Two function
// names sharing a 64-byte-plus common prefix but differing only AFTER byte
// 64 therefore hashed identically in BOTH LOWER_FN_TUPLE_ARR_HASH and
// LOWER_FN_TUPLE_ARR_HASH2, so `lower_fn_tuple_f64_array_mask` could return
// one function's array-slot mask for a DIFFERENT function sharing that
// truncated prefix -- exactly the bits-as-i64 (or, here, the mirror-image
// bits-as-f64) corruption this whole side table exists to prevent, just
// reached via a long-name collision instead of a short-name one.
//
// The two names below share a 64-byte prefix and differ only in their last
// two characters ("aa" vs "bb"). `..aa` returns a tuple of two f64 arrays
// (mask = 3, both slots arrays). `..bb` returns a tuple whose slot 0 is a
// plain [i64; 2] array and whose slot 1 is an [f64; 2] array (mask = 2, only
// slot 1 an array). If the hash were still truncated at 64 bytes, both names
// would collide in the table and `..bb`'s lookup could pick up `..aa`'s
// mask (3) instead of its own (2), wrongly marking `..bb`'s INTEGER slot 0
// as an f64 array too -- so reading its plain i64 elements would misread
// the raw bits as f64 (the mirror image of the original kinetics bug, same
// root cause: a stale/wrong mask from an unrelated function).
fn nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkaa() -> ([f64; 2], [f64; 2]) with Mut, Panic {
    var a: [f64; 2] = [0.0; 2]
    var b: [f64; 2] = [0.0; 2]
    a[0] = 1.5
    b[0] = 0.25
    (a, b)
}

fn nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkbb() -> ([i64; 2], [f64; 2]) with Mut, Panic {
    var ints: [i64; 2] = [0; 2]
    var floats: [f64; 2] = [0.0; 2]
    ints[0] = 7
    floats[0] = 0.25
    (ints, floats)
}

fn main() -> i32 with IO, Mut, Panic {
    let (oa, ob) = nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkaa()
    let s0: f64 = oa[0] * 2.0
    let s1: f64 = 2.0 * ob[0]

    let (ib, fb) = nabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijkbb()
    let v = ib[0] * 2
    let fv: f64 = fb[0] * 2.0

    if s0 == 3.0 && s1 == 0.5 && v == 14 && fv == 0.5 {
        println("TUPLE_ARR_HASH_LONG_NAME_COLLISION PASS")
        return 0
    }
    1
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: TUPLE_SLOT_FIELD_ACCESS_METHOD_AND_LIT_BASE PASS
//
// Copilot review (PR #2516), finding B on the third review round:
// expr_is_tuple_slot_f64_array_ref (self-hosted/ir/lower.sio) only special-
// cased ExprIdent and ExprCall bases for a direct tuple-slot field access
// (`base.0`), falling straight through to `false` for any other base kind
// -- even though expr_result_tuple_arr_mask_ref (extended in an earlier
// round of this same review) already knows how to classify ExprMethodCall
// and ExprTupleLit bases too. So `p.pair().0` (base is a method call) and
// `([x; 2], [y; 2]).0` (base is a tuple literal) both fell back to the
// integer-element path even with no intervening `let` binding at all.
struct Pairer {
    scale: f64,
}

impl Pairer {
    fn pair(self) -> ([f64; 2], [f64; 2]) with Mut, Panic {
        var a: [f64; 2] = [0.0; 2]
        var b: [f64; 2] = [0.0; 2]
        a[0] = 1.5 * self.scale
        b[0] = 4.5
        (a, b)
    }
}

fn main() -> i32 with IO, Mut, Panic {
    let p = Pairer { scale: 1.0 }
    // Direct field access on a METHOD CALL base, no intervening `let (a,b)=`.
    let a = p.pair().0
    let s0: f64 = a[0] * 2.0

    // Direct field access on a TUPLE LITERAL base built from f64 locals.
    let x: f64 = 2.5
    let y: f64 = 0.5
    let lit_slot = ([x; 2], [y; 2]).0
    let s1: f64 = lit_slot[0] * 2.0

    if s0 == 3.0 && s1 == 5.0 {
        println("TUPLE_SLOT_FIELD_ACCESS_METHOD_AND_LIT_BASE PASS")
        return 0
    }
    1
}

//@ run-pass
//@ native-pass
// Bayesian-MCMC Integration Test Suite
//
// Tests the MCMC sampling infrastructure and its integration
// with BayesianKnowledge (epistemic type bridge).
//
// Tests:
//  1. LCG produces values in [0, 1)
//  2. Box-Muller normal proposal is centered around current
//  3. Chain mean/variance computation
//  4. Metropolis-Hastings sampling from known normal target
//  5. Effective sample size computation
//  6. Normal prior log-density
//  7. Uniform prior log-density
//  8. Gamma prior log-density
//  9. Knowledge conversion from chain
// 10. Convergence confidence scoring

// =============================================================================
// Math Helpers
// =============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn min_f64(a: f64, b: f64) -> f64 {
    if a < b { a } else { b }
}

fn sqrt_f64(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x;
    var i = 0
    while i < 20 {
        y = 0.5 * (y + x / y)
        i = i + 1
    }
    y
}

fn pi_val() -> f64 {
    3.14159265358979323846
}

fn ln_f64(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }

    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }

    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 {
        term = term * t2
        sum = sum + term / ((2 * k + 1) as f64)
        k = k + 1
    }
    return 2.0 * sum + (e as f64) * 0.6931471805599453
}

fn cos_approx(x: f64) -> f64 with Mut {
    var a = x
    let twopi = 2.0 * pi_val()
    while a >= twopi { a = a - twopi }
    while a < 0.0 { a = a + twopi }
    if a > pi_val() { a = a - twopi }
    let a2 = a * a
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 15 {
        term = 0.0 - term * a2 / ((2 * n - 1) * 2 * n) as f64
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn lgamma_f64(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 1.0e30 }
    var val = x
    var shift: f64 = 0.0
    while val < 8.0 {
        shift = shift + ln_f64(val)
        val = val + 1.0
    }
    let ln_2pi = 1.8378770664093453
    var result = (val - 0.5) * ln_f64(val) - val + 0.5 * ln_2pi
    let inv_v = 1.0 / val
    let inv_v2 = inv_v * inv_v
    result = result + inv_v / 12.0
    result = result - inv_v * inv_v2 / 360.0
    result = result + inv_v * inv_v2 * inv_v2 / 1260.0
    return result - shift
}

// =============================================================================
// LCG PRNG via RngState struct (VM cannot do &!f64 arithmetic)
// =============================================================================

struct RngState {
    seed: f64
}

fn frac(x: f64) -> f64 with Mut {
    var v = x
    while v >= 1.0 { v = v - 1.0 }
    while v < 0.0 { v = v + 1.0 }
    return v
}

fn lcg_next(rng: &!RngState) -> f64 with Mut {
    let a = 16807.1234
    let c = 0.4231567890
    let s = rng.seed
    rng.seed = frac(a * s + c)
    return rng.seed
}

// =============================================================================
// Box-Muller Normal Proposal
// =============================================================================

fn mcmc_normal_proposal(current: f64, step_size: f64, rng: &!RngState) -> f64 with Mut {
    var u1 = lcg_next(rng)
    if u1 < 1.0e-10 { u1 = 1.0e-10 }
    let u2 = lcg_next(rng)
    let z = sqrt_f64(0.0 - 2.0 * ln_f64(u1)) * cos_approx(2.0 * pi_val() * u2)
    return current + step_size * z
}

// =============================================================================
// MCMC Chain
// =============================================================================

struct MCMCChain {
    samples: [f64; 5000],
    n_stored: i32,
    n_accepted: i32,
    n_total: i32
}

fn mcmc_chain_new() -> MCMCChain {
    return MCMCChain {
        samples: [0.0; 5000],
        n_stored: 0,
        n_accepted: 0,
        n_total: 0
    }
}

fn mcmc_store_sample(chain: &!MCMCChain, value: f64) with Mut {
    if chain.n_stored < 5000 {
        chain.samples[chain.n_stored] = value
        chain.n_stored = chain.n_stored + 1
    }
}

fn mcmc_chain_mean(chain: &MCMCChain) -> f64 with Mut {
    if chain.n_stored == 0 { return 0.0 }
    var sum: f64 = 0.0
    var i: i32 = 0
    while i < chain.n_stored {
        sum = sum + chain.samples[i]
        i = i + 1
    }
    return sum / (chain.n_stored as f64)
}

fn mcmc_chain_variance(chain: &MCMCChain) -> f64 with Mut {
    if chain.n_stored < 2 { return 0.0 }
    let mean = mcmc_chain_mean(chain)
    var sum_sq: f64 = 0.0
    var i: i32 = 0
    while i < chain.n_stored {
        let diff = chain.samples[i] - mean
        sum_sq = sum_sq + diff * diff
        i = i + 1
    }
    return sum_sq / ((chain.n_stored - 1) as f64)
}

fn mcmc_chain_std(chain: &MCMCChain) -> f64 with Mut {
    return sqrt_f64(mcmc_chain_variance(chain))
}

// =============================================================================
// ESS and R-hat
// =============================================================================

fn mcmc_autocorrelation(chain: &MCMCChain, lag: i32) -> f64 with Mut {
    if chain.n_stored < lag + 2 { return 0.0 }
    let mean = mcmc_chain_mean(chain)
    var cov: f64 = 0.0
    var var_sum: f64 = 0.0
    let n = chain.n_stored - lag
    var i: i32 = 0
    while i < n {
        let d1 = chain.samples[i] - mean
        let d2 = chain.samples[i + lag] - mean
        cov = cov + d1 * d2
        var_sum = var_sum + d1 * d1
        i = i + 1
    }
    if var_sum < 1.0e-30 { return 0.0 }
    return cov / var_sum
}

fn mcmc_effective_sample_size(chain: &MCMCChain) -> f64 with Mut {
    if chain.n_stored < 10 { return chain.n_stored as f64 }
    let n = chain.n_stored as f64

    var sum_rho: f64 = 0.0
    var max_check = chain.n_stored / 2
    if max_check > 100 { max_check = 100 }

    var lag: i32 = 1
    while lag < max_check {
        let rho = mcmc_autocorrelation(chain, lag)
        if rho < 0.05 {
            lag = max_check
        } else {
            sum_rho = sum_rho + rho
            lag = lag + 1
        }
    }

    let tau = 1.0 + 2.0 * sum_rho
    if tau < 1.0 { return n }
    return n / tau
}

fn mcmc_split_rhat(chain: &MCMCChain) -> f64 with Mut {
    if chain.n_stored < 10 { return 2.0 }
    let half = chain.n_stored / 2
    let n = half as f64

    var sum1: f64 = 0.0
    var sum2: f64 = 0.0
    var i: i32 = 0
    while i < half {
        sum1 = sum1 + chain.samples[i]
        sum2 = sum2 + chain.samples[i + half]
        i = i + 1
    }
    let mean1 = sum1 / n
    let mean2 = sum2 / n

    var var1: f64 = 0.0
    var var2: f64 = 0.0
    i = 0
    while i < half {
        let d1 = chain.samples[i] - mean1
        let d2 = chain.samples[i + half] - mean2
        var1 = var1 + d1 * d1
        var2 = var2 + d2 * d2
        i = i + 1
    }
    var1 = var1 / (n - 1.0)
    var2 = var2 / (n - 1.0)

    let W = (var1 + var2) / 2.0
    let grand_mean = (mean1 + mean2) / 2.0
    let dm1 = mean1 - grand_mean
    let dm2 = mean2 - grand_mean
    let B = n * (dm1 * dm1 + dm2 * dm2)
    if W < 1.0e-30 { return 1.0 }
    let var_plus = (n - 1.0) / n * W + B / n
    return sqrt_f64(var_plus / W)
}

// =============================================================================
// Prior Log-Densities
// =============================================================================

fn normal_log_density(x: f64, mu: f64, sigma: f64) -> f64 with Mut {
    if sigma <= 0.0 { return 0.0 - 1.0e30 }
    let z = (x - mu) / sigma
    let log_2pi = 1.8378770664093453
    return 0.0 - 0.5 * log_2pi - ln_f64(sigma) - 0.5 * z * z
}

fn uniform_log_density(x: f64, lo: f64, hi: f64) -> f64 with Mut {
    if x < lo { return 0.0 - 1.0e30 }
    if x > hi { return 0.0 - 1.0e30 }
    if hi <= lo { return 0.0 - 1.0e30 }
    return 0.0 - ln_f64(hi - lo)
}

fn gamma_log_density(x: f64, alpha: f64, beta: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if alpha <= 0.0 { return 0.0 - 1.0e30 }
    if beta <= 0.0 { return 0.0 - 1.0e30 }
    return alpha * ln_f64(beta) - lgamma_f64(alpha) + (alpha - 1.0) * ln_f64(x) - beta * x
}

// =============================================================================
// BayesianKnowledge + Quantile + Confidence
// =============================================================================

struct BayesianKnowledge {
    mean: f64,
    std_dev: f64,
    ci_lower: f64,
    ci_upper: f64,
    confidence: f64,
    n_effective: f64
}

fn sort_partial(arr: &![f64; 5000], n: i32) with Mut {
    // Insertion sort
    var i: i32 = 1
    while i < n {
        let key = arr[i]
        var j = i - 1
        while j >= 0 {
            if arr[j] > key {
                arr[j + 1] = arr[j]
                j = j - 1
            } else {
                j = 0 - 1
            }
        }
        arr[j + 1] = key
        i = i + 1
    }
}

fn compute_quantile(chain: &MCMCChain, q: f64) -> f64 with Mut {
    if chain.n_stored == 0 { return 0.0 }
    if chain.n_stored == 1 { return chain.samples[0] }

    var sorted: [f64; 5000] = [0.0; 5000]
    var i: i32 = 0
    while i < chain.n_stored {
        sorted[i] = chain.samples[i]
        i = i + 1
    }
    sort_partial(&!sorted, chain.n_stored)

    let pos = q * ((chain.n_stored - 1) as f64)
    var lo_idx = pos as i32
    if lo_idx < 0 { lo_idx = 0 }
    if lo_idx >= chain.n_stored - 1 { lo_idx = chain.n_stored - 2 }
    let hi_idx = lo_idx + 1
    let frac_val = pos - (lo_idx as f64)
    return sorted[lo_idx] * (1.0 - frac_val) + sorted[hi_idx] * frac_val
}

fn compute_credible_interval(chain: &MCMCChain, level: f64) -> [f64; 2] with Mut {
    let alpha = 1.0 - level
    let lower_q = alpha / 2.0
    let upper_q = 1.0 - alpha / 2.0
    var result: [f64; 2] = [0.0; 2]
    result[0] = compute_quantile(chain, lower_q)
    result[1] = compute_quantile(chain, upper_q)
    return result
}

fn convergence_confidence(ess: f64, r_hat: f64) -> f64 {
    if ess >= 400.0 {
        if r_hat < 1.05 {
            let base = 0.95
            let bonus = min_f64(0.04, (ess - 400.0) / 10000.0)
            return base + bonus
        }
    }
    if ess >= 100.0 {
        if r_hat < 1.10 {
            let base = 0.80
            let bonus = min_f64(0.14, (ess - 100.0) / 3000.0)
            return base + bonus
        }
    }
    return max_f64(0.5, ess / 1000.0)
}

fn chain_to_knowledge_into(out: &!BayesianKnowledge, chain: &MCMCChain) with Mut {
    out.mean = mcmc_chain_mean(chain)
    out.std_dev = mcmc_chain_std(chain)
    out.ci_lower = compute_quantile(chain, 0.025)
    out.ci_upper = compute_quantile(chain, 0.975)
    out.n_effective = mcmc_effective_sample_size(chain)
    let r_hat = mcmc_split_rhat(chain)
    out.confidence = convergence_confidence(out.n_effective, r_hat)
}

