// FLAT PKSens STRUCT
// ============================================================================

struct PKSens {
    s_ti: [f64; 8],
    s_i: [f64; 8],
    n_params: i64,
    dom_idx: i64,
    dom_s_ti: f64,
    cl_dominant: i64
}

fn empty_sens() -> PKSens {
