    if sed_moufang_middle_nsq(&e1e, &e2e, &e4e) > 1.0e-9 { ok = 0 }
    if sed_moufang_right_nsq(&e1e, &e2e, &e4e) > 1.0e-9 { ok = 0 }

    if ok == 1 { 0 } else { 1 }
}

